CREATE OR REPLACE FUNCTION public.fn_agenda_excepciones_sucursal_bloques_validar_modo()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_modo text;
BEGIN
  SELECT e.modo_excepcion_codigo
    INTO v_modo
  FROM public.agenda_excepciones_sucursal e
  WHERE e.id_excepcion_sucursal = NEW.id_excepcion_sucursal;

  IF v_modo IS NULL THEN
    RAISE EXCEPTION 'La excepción de sucursal no existe.'
      USING ERRCODE = '23503';
  END IF;

  IF v_modo = 'cierre_total' THEN
    RAISE EXCEPTION 'cierre_total no permite bloques horarios.'
      USING ERRCODE = '23514';
  END IF;

  IF v_modo NOT IN ('cierre_parcial', 'horario_especial', 'apertura_extra') THEN
    RAISE EXCEPTION 'Modo de excepción de sucursal no soporta bloques horarios.'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_agenda_excepciones_sucursal_validar_compatibilidad()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.modo_excepcion_codigo = 'cierre_total' THEN
    IF EXISTS (
      SELECT 1
      FROM public.agenda_excepciones_sucursal e
      WHERE e.id_sucursal = NEW.id_sucursal
        AND e.fecha = NEW.fecha
        AND e.id_excepcion_sucursal <> NEW.id_excepcion_sucursal
    ) THEN
      RAISE EXCEPTION 'No se puede registrar cierre_total junto con otras excepciones de sucursal para la misma fecha.'
        USING ERRCODE = '23514';
    END IF;
  ELSE
    IF EXISTS (
      SELECT 1
      FROM public.agenda_excepciones_sucursal e
      WHERE e.id_sucursal = NEW.id_sucursal
        AND e.fecha = NEW.fecha
        AND e.id_excepcion_sucursal <> NEW.id_excepcion_sucursal
        AND e.modo_excepcion_codigo = 'cierre_total'
    ) THEN
      RAISE EXCEPTION 'No se puede registrar una excepción de sucursal cuando ya existe cierre_total para la misma fecha.'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.modo_excepcion_codigo IN ('horario_especial', 'apertura_extra') THEN
    IF EXISTS (
      SELECT 1
      FROM public.agenda_excepciones_sucursal e
      WHERE e.id_sucursal = NEW.id_sucursal
        AND e.fecha = NEW.fecha
        AND e.id_excepcion_sucursal <> NEW.id_excepcion_sucursal
        AND e.modo_excepcion_codigo IN ('horario_especial', 'apertura_extra')
    ) THEN
      RAISE EXCEPTION 'No se puede combinar horario_especial y apertura_extra en la misma sucursal y fecha.'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.modo_excepcion_codigo = 'cierre_total' THEN
    IF EXISTS (
      SELECT 1
      FROM public.agenda_excepciones_sucursal_bloques b
      WHERE b.id_excepcion_sucursal = NEW.id_excepcion_sucursal
    ) THEN
      RAISE EXCEPTION 'cierre_total no debe tener bloques horarios.'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_bloquear_persona_cliente_empleado()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_TABLE_NAME = 'empleados' THEN
    IF EXISTS (
      SELECT 1
      FROM public.clientes c
      WHERE c.id_persona = NEW.id_persona
        AND c.deleted_at IS NULL
    ) THEN
      RAISE EXCEPTION 'La persona ya existe como cliente y no puede crearse como empleado';
    END IF;
  ELSIF TG_TABLE_NAME = 'clientes' THEN
    IF EXISTS (
      SELECT 1
      FROM public.empleados e
      WHERE e.id_persona = NEW.id_persona
        AND e.deleted_at IS NULL
    ) THEN
      RAISE EXCEPTION 'La persona ya existe como empleado y no puede crearse como cliente';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_citas_detalles_line_identity_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
DECLARE
  v_orden_integrante integer;
  v_next_order integer;
  v_occurrence integer;
  v_expected_key text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.id_cita IS DISTINCT FROM OLD.id_cita
       OR NEW.id_servicio IS DISTINCT FROM OLD.id_servicio
       OR NEW.id_tarifa IS DISTINCT FROM OLD.id_tarifa
       OR NEW.origen_item_codigo IS DISTINCT FROM OLD.origen_item_codigo
       OR NEW.orden_linea IS DISTINCT FROM OLD.orden_linea
       OR NEW.line_key IS DISTINCT FROM OLD.line_key THEN
      RAISE EXCEPTION USING
        ERRCODE = 'P0001',
        MESSAGE = 'MF_BOOKING_LINE_IDENTITY_IMMUTABLE';
    END IF;
    RETURN NEW;
  END IF;

  SELECT COALESCE(c.orden_integrante, 1)
  INTO v_orden_integrante
  FROM public.citas c
  WHERE c.id_cita = NEW.id_cita;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '23503',
      MESSAGE = 'MF_BOOKING_LINE_APPOINTMENT_NOT_FOUND';
  END IF;

  IF NEW.orden_linea IS NULL OR NEW.orden_linea < 1 THEN
    SELECT COALESCE(max(cd.orden_linea), 0) + 1
    INTO v_next_order
    FROM public.citas_detalles cd
    WHERE cd.id_cita = NEW.id_cita;
    NEW.orden_linea := GREATEST(1, COALESCE(v_next_order, 1));
  END IF;

  SELECT count(*)::integer + 1
  INTO v_occurrence
  FROM public.citas_detalles cd
  WHERE cd.id_cita = NEW.id_cita
    AND cd.id_servicio = NEW.id_servicio
    AND cd.id_tarifa IS NOT DISTINCT FROM NEW.id_tarifa
    AND cd.origen_item_codigo = NEW.origen_item_codigo;

  v_expected_key := app_private.build_booking_line_key_v1(
    v_orden_integrante,
    NEW.id_servicio,
    NEW.id_tarifa,
    NEW.origen_item_codigo,
    v_occurrence
  );

  IF NULLIF(btrim(NEW.line_key), '') IS NULL THEN
    NEW.line_key := v_expected_key;
  ELSIF NEW.line_key IS DISTINCT FROM v_expected_key THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'MF_BOOKING_LINE_KEY_MISMATCH',
      DETAIL = format('expected=%s received=%s', v_expected_key, NEW.line_key);
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_citas_grupos_set_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.id_grupo_cita IS NULL THEN
    NEW.id_grupo_cita := gen_random_uuid();
  END IF;

  IF NEW.codigo_reserva IS NULL OR btrim(NEW.codigo_reserva) = '' THEN
    NEW.codigo_reserva :=
      'MF-RSV-' ||
      to_char(COALESCE(NEW.created_at, now()), 'YYYYMMDD') ||
      '-' ||
      upper(left(replace(NEW.id_grupo_cita::text, '-', ''), 8));
  END IF;

  IF NEW.origen_codigo IS NULL OR btrim(NEW.origen_codigo) = '' THEN
    NEW.origen_codigo := 'publico';
  END IF;

  IF NEW.total_hnl IS NULL THEN
    NEW.total_hnl := 0;
  END IF;

  RETURN NEW;
END;
$function$

