CREATE OR REPLACE FUNCTION public.fn_prevent_block_protected_role()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_super_admin_rol uuid;
BEGIN
  SELECT id_rol
  INTO v_super_admin_rol
  FROM public.roles
  WHERE lower(nombre) = 'super_admin'
  LIMIT 1;

  IF EXISTS (
    SELECT 1
    FROM public.app_protected_users apu
    WHERE apu.id_usuario = NEW.id_usuario
      AND apu.activo IS TRUE
  )
  AND NEW.id_rol = v_super_admin_rol THEN

    IF NEW.activo IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'ROOT_SUPER_ADMIN_ROLE_CANNOT_BE_DISABLED';
    END IF;

    IF NEW.id_sucursal IS NOT NULL THEN
      RAISE EXCEPTION 'ROOT_SUPER_ADMIN_ROLE_MUST_BE_GLOBAL';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_prevent_block_protected_usuario()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.app_protected_users apu
    WHERE apu.id_usuario = NEW.id_usuario
      AND apu.activo IS TRUE
  ) THEN
    IF NEW.estado IS DISTINCT FROM true THEN
      RAISE EXCEPTION 'ROOT_USER_CANNOT_BE_DISABLED';
    END IF;

    IF NEW.deleted_at IS NOT NULL THEN
      RAISE EXCEPTION 'ROOT_USER_CANNOT_BE_DELETED';
    END IF;

    IF NEW.estado_acceso IS DISTINCT FROM 'activo' THEN
      RAISE EXCEPTION 'ROOT_USER_CANNOT_BE_BLOCKED';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

