CREATE OR REPLACE FUNCTION public.fn_trg_roles_usuarios_unicidad_scope()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_nombre_rol text;
  v_existe boolean;
BEGIN
  SELECT lower(nombre)
  INTO v_nombre_rol
  FROM public.roles
  WHERE id_rol = NEW.id_rol;

  IF v_nombre_rol IN ('super_admin', 'cliente', 'root') THEN
    IF NEW.id_sucursal IS NOT NULL THEN
      RAISE EXCEPTION 'ROL_GLOBAL_NO_DEBE_TENER_SUCURSAL';
    END IF;
  ELSE
    IF NEW.id_sucursal IS NULL THEN
      RAISE EXCEPTION 'ROL_REQUIERE_SUCURSAL';
    END IF;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.roles_usuarios ru
    WHERE ru.id_rol = NEW.id_rol
      AND ru.id_usuario = NEW.id_usuario
      AND ru.id_sucursal IS NOT DISTINCT FROM NEW.id_sucursal
      AND (TG_OP = 'INSERT' OR ru.id_rol_usuario <> NEW.id_rol_usuario)
  )
  INTO v_existe;

  IF v_existe THEN
    RAISE EXCEPTION 'ROL_USUARIO_DUPLICADO_MISMO_SCOPE';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_trg_validar_cliente_persona_en_cita()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_persona_cliente uuid;
BEGIN
  IF NEW.id_cliente IS NOT NULL THEN
    SELECT id_persona INTO v_persona_cliente FROM clientes WHERE id_cliente = NEW.id_cliente;
    IF v_persona_cliente IS DISTINCT FROM NEW.id_persona_cliente THEN
      RAISE EXCEPTION 'CLIENTE_NO_COINCIDE_CON_PERSONA_EN_CITA';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_persona_empleado_campos_obligatorios()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_dni text;
  v_telefono text;
  v_existe_empleado_activo boolean;
BEGIN
  -- Caso A: se inserta/actualiza empleado
  IF TG_TABLE_NAME = 'empleados' THEN
    -- Si el registro de empleado se está soft-deleteando, no validar
    IF NEW.deleted_at IS NOT NULL THEN
      RETURN NEW;
    END IF;

    SELECT
      regexp_replace(COALESCE(p.dni, ''), '\D', '', 'g'),
      BTRIM(COALESCE(p.telefono_principal, ''))
    INTO
      v_dni,
      v_telefono
    FROM public.personas p
    WHERE p.id_persona = NEW.id_persona
      AND p.deleted_at IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION
        USING ERRCODE = '23514',
              MESSAGE = 'No se puede crear/actualizar empleado: la persona asociada no existe o está eliminada.';
    END IF;

    IF v_dni = '' THEN
      RAISE EXCEPTION
        USING ERRCODE = '23514',
              MESSAGE = 'No se puede crear/actualizar empleado: el DNI es obligatorio para empleados.';
    END IF;

    IF v_telefono = '' THEN
      RAISE EXCEPTION
        USING ERRCODE = '23514',
              MESSAGE = 'No se puede crear/actualizar empleado: el teléfono principal es obligatorio para empleados.';
    END IF;

    RETURN NEW;
  END IF;

  -- Caso B: se actualiza persona que ya está vinculada a un empleado activo
  IF TG_TABLE_NAME = 'personas' THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.empleados e
      WHERE e.id_persona = NEW.id_persona
        AND e.deleted_at IS NULL
    )
    INTO v_existe_empleado_activo;

    IF v_existe_empleado_activo THEN
      IF regexp_replace(COALESCE(NEW.dni, ''), '\D', '', 'g') = '' THEN
        RAISE EXCEPTION
          USING ERRCODE = '23514',
                MESSAGE = 'No se puede actualizar la persona: el DNI es obligatorio porque está vinculada a un empleado activo.';
      END IF;

      IF BTRIM(COALESCE(NEW.telefono_principal, '')) = '' THEN
        RAISE EXCEPTION
          USING ERRCODE = '23514',
                MESSAGE = 'No se puede actualizar la persona: el teléfono principal es obligatorio porque está vinculada a un empleado activo.';
      END IF;
    END IF;

    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_current_timestamp_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_membership_plan_beneficios()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  servicios_count INT;
BEGIN
  IF NEW.beneficios IS NULL THEN
    RAISE EXCEPTION 'PLAN_BENEFICIOS_REQUIRED';
  END IF;

  -- Validar que exista array de servicios
  IF NOT (NEW.beneficios ? 'servicios') THEN
    RAISE EXCEPTION 'PLAN_SERVICIOS_REQUIRED';
  END IF;

  SELECT jsonb_array_length(NEW.beneficios->'servicios')
  INTO servicios_count;

  IF servicios_count < 1 THEN
    RAISE EXCEPTION 'PLAN_SERVICIOS_MIN_REQUIRED';
  END IF;

  RETURN NEW;
END;
$function$
